code='''from collections import deque

def transform(grid):
    a=[row[:] for row in grid]
    h,w=len(a),len(a[0])
    seen=set()
    for r in range(h):
        for c in range(w):
            color=a[r][c]
            if color==9 or (r,c) in seen:
                continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and a[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            if r1-r0<2 or c1-c0<2:
                continue
            # A rectangular outline surrounds the region; fill its cavity by parity.
            if all(a[r0][x]==color and a[r1][x]==color for x in range(c0,c1+1)) and all(a[y][c0]==color and a[y][c1]==color for y in range(r0,r1+1)):
                iw,ih=c1-c0-1,r1-r0-1
                fill=7 if iw%2==1 and ih%2==1 else 2
                for y in range(r0+1,r1):
                    for x in range(c0+1,c1):
                        if a[y][x]==9:
                            a[y][x]=fill
    return a
'''
